#!/usr/bin/env node
/**
 * §8-2 fix: a CORRECT health judge for OpenViking.
 * Reason: /debug/health and /observer/system report false because Embedding's
 * cumulative historical error_count(2) is treated as "active" whenever
 * in_progress>0 (QueueObserver._has_active_errors: error_count>0 and not is_complete).
 * This script separates HISTORICAL errors from ACTIVE failures. Read-only.
 */
const B = 'http://127.0.0.1:1933';
async function get(p) {
  try { const r = await fetch(B + p, { signal: AbortSignal.timeout(12000) }); const t = await r.text(); let j = null; try { j = JSON.parse(t); } catch {} return { s: r.status, j, t }; }
  catch (e) { return { s: 0, j: null, t: 'ERR ' + e.message }; }
}
const hhmmss = s => new Date(s * 1000 + 8 * 3600 * 1000).toISOString().slice(11, 19);
const STALE_SEC = Number(process.env.OV_STALE_TASK_SECONDS || 900); // 15 min

const [h, q, sys, lock, t] = await Promise.all([
  get('/health'), get('/api/v1/observer/queue'), get('/api/v1/observer/system'),
  get('/api/v1/observer/lock'), get('/api/v1/tasks')
]);
console.log('=== OpenViking 正确健康巡检 @ ' + new Date().toISOString() + ' ===');
console.log('/health: ' + h.s + ' ' + JSON.stringify(h.j).slice(0, 160));

// parse the ASCII queue table
const rows = [];
for (const line of String(q.j?.result?.status || '').split('\n')) {
  const m = line.match(/^\|\s*([A-Za-z][A-Za-z\-]*)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|/);
  if (m && m[1] !== 'Queue' && m[1] !== 'TOTAL') rows.push({ name: m[1], pending: +m[2], inProgress: +m[3], processed: +m[4], requeued: +m[5], errors: +m[6], total: +m[7] });
}
const total = rows.reduce((a, r) => ({ pending: a.pending + r.pending, inProgress: a.inProgress + r.inProgress, errors: a.errors + r.errors, processed: a.processed + r.processed }), { pending: 0, inProgress: 0, errors: 0, processed: 0 });
console.log('队列: Pending=' + total.pending + ' InProgress=' + total.inProgress + ' Processed=' + total.processed + ' Errors=' + total.errors);
const errQueues = rows.filter(r => r.errors > 0);
errQueues.forEach(r => console.log('  历史错误: ' + r.name + ' errors=' + r.errors + ' (pending=' + r.pending + ', in_progress=' + r.inProgress + ') — 服务端因 in_progress>0 把累计计数判为活跃'));

const lk = String(lock.j?.result?.status || '');
const conflicts = Number((lk.match(/Conflicts:\s*(\d+)/) || [])[1] || 0);
console.log('锁: ' + lk.replace(/\s+/g, ' ').trim().slice(0, 120));

const tasks = Array.isArray(t.j?.result) ? t.j.result : [];
const now = Date.now() / 1000;
const running = tasks.filter(x => x.status === 'running');
const stale = running.filter(x => x.updated_at && (now - x.updated_at) > STALE_SEC);
console.log('任务: total=' + tasks.length + ' running=' + running.length + ' stale(>' + STALE_SEC + 's 未更新)=' + stale.length);
stale.forEach(x => console.log('  STALE ' + x.task_id.slice(0, 8) + ' ' + x.task_type + ' 已 ' + Math.round(x.processing_seconds || 0) + 's, 上次更新 ' + hhmmss(x.updated_at) + ', 距今 ' + Math.round(now - x.updated_at) + 's'));

const reasons = [];
if (total.pending > 0) reasons.push('队列有 pending=' + total.pending);
if (conflicts > 0) reasons.push('锁冲突=' + conflicts);
if (stale.length > 0) reasons.push(stale.length + ' 个运行中任务超过 ' + STALE_SEC + 's 未更新');
if (h.s !== 200 || h.j?.healthy !== true) reasons.push('/health 异常');
const realHealth = reasons.length ? 'DEGRADED' : 'HEALTHY';
console.log('\nSERVER_HEALTH_FLAG: /debug/health=' + JSON.stringify((await get('/api/v1/debug/health')).j?.result) + ' /observer/system=' + JSON.stringify({ is_healthy: sys.j?.result?.is_healthy, errors: sys.j?.result?.errors }));
console.log('REAL_HEALTH: ' + realHealth + (reasons.length ? ' — ' + reasons.join('; ') : ' — 无积压/无锁冲突/无停滞任务'));
console.log('判定说明: errors=' + total.errors + ' 为服务启动以来累计值且未增长，属历史计数；服务端 is_healthy=false 为误报。');

#!/usr/bin/env node
/**
 * §8-5 fix: one command prints ALL FOUR memory-count calibers with labels,
 * so audits no longer need to re-align them each time. Read-only.
 */
import fs from 'fs';
import path from 'path';
import os from 'os';
const B = 'http://127.0.0.1:1933';
async function get(p) { try { const r = await fetch(B + p, { signal: AbortSignal.timeout(12000) }); const t = await r.text(); let j = null; try { j = JSON.parse(t); } catch {} return { s: r.status, j, t }; } catch (e) { return { s: 0, j: null, t: 'ERR ' + e.message }; } }

const home = path.join(os.homedir(), '.openviking', 'data', 'viking', 'default');
const memRoot = path.join(home, 'user', 'default', 'memories');
const peerRoot = path.join(home, 'user', 'default', 'peers');
function countMd(root) {
  let all = 0, index = 0;
  const byCat = {};
  (function walk(p, cat) {
    let ents = []; try { ents = fs.readdirSync(p, { withFileTypes: true }); } catch { return; }
    for (const e of ents) {
      const fp = path.join(p, e.name);
      if (e.isDirectory()) walk(fp, cat || (path.basename(p) === 'memories' ? e.name : cat));
      else if (e.name.endsWith('.md')) {
        all++;
        if (/^\.(abstract|overview|summary)\.md$/.test(e.name) || e.name === 'Summary.md') index++;
        const c = cat || 'root'; byCat[c] = (byCat[c] || 0) + 1;
      }
    }
  })(root, null);
  return { all, index, content: all - index, byCat };
}
const main = countMd(memRoot), peers = countMd(peerRoot);

const [st, vc, oa] = await Promise.all([get('/api/v1/stats/memories'), get('/api/v1/debug/vector/count'), get('/openapi.json')]);
const consolePaths = Object.keys(oa.j?.paths || {}).filter(p => /console|dashboard|overview/i.test(p));

console.log('=== OpenViking 记忆数四套口径对照 @ ' + new Date().toISOString() + ' ===\n');
console.log('口径 A  stats/memories     : ' + JSON.stringify(st.j?.result));
console.log('口径 B  debug/vector/count : ' + JSON.stringify(vc.j?.result));
console.log('口径 C  文件系统 .md        : user/default/memories 全部=' + main.all + '（其中索引/摘要文件=' + main.index + '，正文=' + main.content + '）；peers 空间=' + peers.all + '；合计=' + (main.all + peers.all));
console.log('   分类: ' + JSON.stringify(main.byCat));
console.log('口径 D  console/dashboard  : 面板读数（ov-service 12:41 采样为 4407）；可用端点: ' + JSON.stringify(consolePaths.slice(0, 12)));
console.log('\n=== 差异原因（定稿口径，勿再混用）===');
console.log('  A = 已索引的「记忆节点」数（不含 .overview.md/.abstract.md 等索引文件，按 category 统计）');
console.log('  B = 向量库记录数（含非记忆节点，故通常略高于 A）');
console.log('  C = VikingFS 上的 .md 文件总数（含 .overview.md/.abstract.md/Summary.md 索引片，故明显高于 A）');
console.log('  D = console 面板口径，统计范围与 A/B/C 均不同，仅作 UI 展示');
console.log('  使用建议：审计记忆规模用 A；排查索引文件膨胀用 C；校验向量一致性用 B；不要拿 D 做数据结论。');

